#include <stdio.h>

int main(void)
{
    unsigned long F_CPU = 16000000UL;
    unsigned int  N     = 64;
    unsigned int  ocr   = 63;

    printf("%lu\n", F_CPU / ((unsigned long)N * 256));
    printf("%u\n",  (unsigned)((ocr + 1) * 100 / 256));
    return 0;
}

#include <stdio.h>

int main(void)
{
    unsigned long f    = 16000000UL;
    unsigned long baud = 9600UL;

    unsigned int  ubrr   = (unsigned int)(f / (16UL * baud) - 1);
    unsigned long actual = f / (16UL * (ubrr + 1));

    printf("%u %lu\n", ubrr, actual);
    return 0;
}

