    return 0;
}

#include <stdio.h>

int main(void)
{
    unsigned long act_ua = 10000;   /* 10 mA = 10000 uA */
    unsigned long slp_ua = 2;       /* 2 uA            */
    unsigned long ta     = 5;       /* ms              */
    unsigned long ts     = 995;     /* ms              */

    unsigned long avg = (act_ua * ta + slp_ua * ts) / (ta + ts);

    printf("%lu\n", avg);
    return 0;
}
